/**
 * Document storage. Local disk by default (DOCUMENT_DIR); keys are generated by the server
 * (year/month/uuid), never taken from the user. Swap for an S3-compatible adapter in production
 * by implementing the same three functions.
 */
const fs = require('fs/promises');
const path = require('path');
const crypto = require('crypto');

const ROOT = path.resolve(process.env.DOCUMENT_DIR || path.join(__dirname, '..', '..', process.env.NODE_ENV === 'test' ? 'uploads-test' : 'uploads'));

const newKey = () => { const d = new Date(); return `${d.getUTCFullYear()}/${String(d.getUTCMonth() + 1).padStart(2, '0')}/${crypto.randomUUID()}`; };
const fileFor = (key) => {
  if (!/^\d{4}\/\d{2}\/[0-9a-f-]{36}$/.test(key)) throw new Error('Invalid storage key');
  return path.join(ROOT, key);
};

async function put(buffer) {
  const key = newKey();
  const file = fileFor(key);
  await fs.mkdir(path.dirname(file), { recursive: true });
  await fs.writeFile(file, buffer, { flag: 'wx' });
  return key;
}
const get = (key) => fs.readFile(fileFor(key));
const remove = (key) => fs.rm(fileFor(key), { force: true });

module.exports = { put, get, remove, ROOT };
